const state = options.getState();
const itemId = state.grid.selectedRows[0];
if (window.execInTearOffWin(itemId, 'revisions')) {
	return;
}

const dialogParams = {
	aras: window.aras,
	itemID: itemId,
	itemTypeName: options.itemTypeName,
	title: window.aras.getResource('', 'revisiondlg.item_versions'),
	type: 'RevisionsDialog'
};

window.parent.ArasModules.MaximazableDialog.show('iframe', dialogParams);
